FilterOperatorDetailsBase.definition:
{
    /* The i18n key for the operator. */
    key: string;
    /* The operator value. Usually the string representation of the operator. */
    value: OperatorValue;
    /* How much data the operator applies to. */
    target: FilterOperatorTarget;
    /* The plural form of the operator, if applicable. */
    singularOf?: FilterOperators[T];
    /* The singular form of the operator, if applicable. */
    pluralOf?: FilterOperators[T];
    /* All related operators. Normally, all the operators which share the same target. */
    relativeOf: FilterOperators[T] | Array<FilterOperators[T]>;
    /* Whether the operator is negated. */
    isNegated: boolean;
    /* If the operator is not negated, this provides the negated equivalent. */
    negation?: FilterOperators[T];
    /* If the operator is negated, this provides the positive equivalent. */
    negationOf?: FilterOperators[T];
}

FilterOperatorDetails.definition:
FilterOperatorDetailsBase<OperatorValue, T> & ({
    singularOf?: never;
    pluralOf?: never;
} | {
    target: 'single';
    singularOf: FilterOperators[T];
    pluralOf?: never;
} | {
    target: 'multiple';
    singularOf?: never;
    pluralOf: FilterOperators[T];
}) & ({
    isNegated: false;
    negation: FilterOperators[T];
    negationOf?: never;
} | {
    isNegated: true;
    negation?: never;
    negationOf: FilterOperators[T];
})

UseFilteredNodesOptions.definition:
{
    /**
     * Filter mode.
     * - 'shallow': Return top-level nodes only (default for action menus)
     * - 'deep': Include nested submenu children (default for command menus)
     */
    mode?: FilterMode;
    /**
     * Whether streaming mode is enabled.
     * In streaming mode, results are sorted by completion order to prevent jumping.
     */
    streamingEnabled?: boolean;
    /**
     * Loader completion order (for streaming mode).
     * Array of submenu IDs in the order they completed loading.
     */
    completionOrder?: string[];
    /**
     * Custom sort function to override default sorting.
     * Applied after scoring but before partitioning and deduplication.
     */
    customSort?: (a: any, b: any) => number;
    /**
     * Custom filter function to filter out nodes.
     * Applied after scoring but before sorting.
     */
    customFilter?: (node: Node<any>) => boolean;
    /**
     * Optional control instance for programmatic menu manipulation.
     * Will be passed to middleware transformNodes context.
     */
    control?: any;
    /**
     * Whether the menu is currently disabled.
     * Will be passed to middleware transformNodes context.
     */
    disabled?: boolean;
}

UseFilteredNodesResult.definition:
{
    /**
     * Filtered and sorted nodes with search metadata.
     * These are the nodes that match the query (or all nodes if no query).
     */
    filteredNodes: Node<T>[];
    /**
     * Display nodes ready for rendering.
     * In streaming mode, includes a loading node at the end if loaders are in progress.
     */
    displayNodes: Node<T>[];
}

